function sizeOptions(){return ['P','M','G','GG','G1','G2','G3'].map(x=>`<option>${x}</option>`).join('');}
export function loginBody(error){return `<div class="login-theme"><button type="button" class="theme-button" data-braza-theme-toggle aria-label="Alternar tema">Tema claro / escuro</button></div><main class="login card"><div class="brand"><span class="brand-mark">B</span><div>BrazaCommerce<small>Sua loja em um só lugar</small></div></div><h1>Entre para acompanhar sua loja</h1><p class="muted login-description">Vendas, anúncios, produtos e custos no mesmo painel.</p>${error?'<p class="alert" role="alert">Usuário ou senha não conferem. Tente novamente.</p>':''}<form method="post" action="/login"><label for="username">Usuário</label><input id="username" name="username" autocomplete="username" required maxlength="100"><label for="password">Senha</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="200"><button type="submit">Entrar</button></form><p class="login-note">Use seu acesso já cadastrado. As opções disponíveis acompanham as permissões da sua conta.</p></main>`;}

function legacyAdminBody(){return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="/admin?tab=overview"><span class="brand-mark">B</span><div>BrazaCommerce<small>GESTÃO DA LOJA</small></div></a><div class="sidebar-navigation">${workspaceNavigation('overview',{role:'owner'})}</div><div class="sidebar-foot"><p>Os resultados da loja e dos anúncios ficam em áreas próprias, com as mesmas datas.</p></div></aside><div class="main-wrap"><header class="topbar"><div class="workspace-context"><span class="brand-mark" aria-hidden="true">B</span><strong>BrazaCommerce</strong><small>Minha loja · Shopee Brasil</small></div><div class="top-actions"><span class="status-pill" id="connection">Carregando…</span><button type="button" class="theme-button" data-braza-theme-toggle aria-label="Alternar tema">Claro / escuro</button><div class="workspace-header-menu">${workspaceSecondaryNavigation('overview',{role:'owner'})}</div><form method="post" action="/admin/logout" id="logout" hidden><button class="button-link">Sair</button></form></div></header><main class="workspace"><div class="hero"><div><div class="eyebrow">VISÃO DO NEGÓCIO</div><h1 id="pageTitle">Visão geral</h1><p id="pageSubtitle" class="muted">Acompanhe o mês, entenda o resultado e encontre o que precisa de atenção.</p></div><span class="badge live-badge">Dados da sua loja</span></div><p id="message" role="status" aria-live="polite"></p>
<section id="overview"><div class="card store-result"><div class="card-head"><div><span class="eyebrow">FINANCEIRO DA LOJA</span><h2>Seu resultado no período</h2><p class="muted">Repasses dos pedidos concluídos, custos de produção e imposto. Anúncios do período aparecem separadamente.</p></div></div><p class="scope-note">Pedidos concluídos criados no período · custos atuais de produção · repasse previsto da Shopee.</p><div id="storePeriodMetrics" class="report-metrics store-result-metrics"></div><div id="storeNetAction" class="store-net-action" hidden><p id="storeNetActionInfo"></p><button id="storeOtherExpensesAction" type="button" class="button-secondary">Informar outras despesas</button></div><div class="store-period-controls"><div class="field"><label for="storePeriodStart">Data inicial · Brasília</label><input id="storePeriodStart" type="date"></div><div class="field"><label for="storePeriodEnd">Data final · Brasília</label><input id="storePeriodEnd" type="date"></div><button id="storePeriodStartButton" type="button">Atualizar agora</button></div><div class="actions"><button id="storePeriodContinue" type="button" class="button-secondary" hidden>Continuar coleta</button><button id="storePeriodStop" type="button" class="button-secondary" hidden>Pausar coleta</button><button id="storePeriodRecalculate" type="button" class="button-link" hidden>Recalcular com custos salvos</button></div><p id="storePeriodStatus" role="status" aria-live="polite" class="field-help">Escolha até 15 dias. Os valores são atualizados automaticamente ao abrir o painel.</p><p id="storePeriodScope" class="field-help"></p><ul id="storePeriodPending" class="store-result-pending"></ul><div id="storePeriodProducts" class="store-pending-products" hidden></div><div id="storeInvoiceTaxReport" class="store-invoice-tax" hidden><strong>Imposto de 2% sobre os produtos</strong><p id="storeInvoiceTaxStatus" class="field-help"></p><div id="storeInvoiceTaxMetrics" class="store-invoice-tax-metrics"></div></div><div id="storeAdsMetrics" class="store-ads-measurement" hidden></div><form id="storeAdjustmentsForm" hidden novalidate><h3>Anúncios e outras despesas deste período</h3><p class="field-help">O gasto de anúncios é consultado para as mesmas datas, mas abrange vendas ainda em andamento. Registre outras despesas fora da Shopee; esses valores ficam separados até a conciliação. O imposto de 2% é estimado automaticamente.</p><p id="storeExternalExpensesReview" class="alert" hidden role="status">O valor anterior foi preservado. Retire o imposto de 2% se ele já estiver incluído nas outras despesas antes de salvar.</p><div class="store-ads-source-controls"><div class="field"><label for="storeAdsSource">Fonte do gasto de anúncios</label><select id="storeAdsSource"><option value="SHOPEE_PERIOD">Shopee Ads · automático</option><option value="MANUAL">Informar manualmente</option></select></div><button id="storeAdsRefresh" type="button" class="button-secondary" disabled>Atualizar anúncios</button></div><p id="storeAdsStatus" class="field-help" role="status" aria-live="polite"></p><p class="field-help store-ads-basis">Anúncios: consumo nas datas selecionadas. Financeiro: pedidos criados nessas datas e já concluídos. As fontes têm recortes diferentes; o fuso do relatório de anúncios ainda não foi confirmado. O cálculo não atribui o gasto a pedidos ou produtos.</p><div class="cost-pair-grid"><div class="field"><label for="storeAdjustmentsAds">Gasto com anúncios no período</label><div class="input-unit"><span>R$</span><input id="storeAdjustmentsAds" inputmode="decimal" autocomplete="off" placeholder="Pendente: aguardando todos os dias" readonly aria-readonly="true"></div></div><div class="field"><label for="storeAdjustmentsExpenses">Outras despesas, sem o imposto de 2%</label><div class="input-unit"><span>R$</span><input id="storeAdjustmentsExpenses" inputmode="decimal" autocomplete="off" placeholder="Informe o gasto, inclusive se for zero"></div></div></div><p class="field-help">Comissões, taxas e frete já incorporados ao repasse da Shopee não devem ser descontados novamente aqui.</p><div class="field"><label for="storeAdjustmentsRecharge">O ajuste financeiro de anúncios ou suporte corresponde a quê?</label><select id="storeAdjustmentsRecharge"><option value="UNCONFIRMED">Ainda não conferi / sem ajuste no período</option><option value="ADS_RECHARGE">Recarga de saldo de anúncios</option><option value="TECH_SUPPORT">Taxa de suporte técnico</option></select><p id="storeAdjustmentsRechargeInfo" class="field-help"></p><p class="field-help">Recarga de saldo e gasto em anúncios são movimentos diferentes. A recarga e a taxa de suporte precisam ser distinguidas na conciliação; uma taxa de suporte já faz parte do repasse.</p></div><div class="form-footer"><p id="storeAdjustmentsVersion" class="field-help"></p><div class="store-expense-actions"><button id="storeNoOtherExpenses" type="button" class="button-secondary" disabled>Não tenho outras despesas</button><button id="storeAdjustmentsSave" disabled>Salvar outras despesas</button></div></div></form><p class="field-help">Produção calculada pelos tamanhos identificados e pelo custo padrão cadastrado. Valores previstos podem mudar até a liquidação.</p></div><div id="storeReturnsReport" class="card store-returns-report" hidden><div class="card-head"><div><span class="eyebrow">COBERTURA DOS PEDIDOS</span><h2>Devoluções e pendências</h2><p class="muted">Veja quais pedidos têm ocorrência de devolução e onde ainda falta informação.</p></div></div><p id="storeReturnsScope" class="field-help"></p><div id="storeReturnsGroups" class="store-return-groups"></div><p class="field-help">Os valores são o repasse previsto dos pedidos de cada grupo. As ocorrências não informam aqui o valor reembolsado nem quais itens foram afetados; recebimentos ainda aguardam conciliação.</p></div><div id="storeProductReport" class="card store-product-report" hidden><div class="card-head"><div><span class="eyebrow">MESMO PERÍODO FINANCEIRO</span><h2>Resultado por produto</h2><p class="muted">Compare unidades, repasse previsto, produção e imposto no mesmo período.</p></div></div><p id="storeProductScope" class="field-help"></p><div id="storeProductAllocation" class="store-product-allocation"></div><div class="store-product-report-filters"><div class="field store-product-report-search"><label for="storeProductSearch">Buscar pelo código do produto</label><input id="storeProductSearch" type="search" inputmode="numeric" autocomplete="off" placeholder="Ex.: 58269212782" aria-controls="storeProductRows"></div><details id="storeProductReportFilters" class="store-product-report-advanced"><summary>Filtros e ordenação</summary><div class="store-product-report-filter-fields"><div class="field store-product-return-filter"><label for="storeProductReturnsFilter">Devolução nos pedidos</label><select id="storeProductReturnsFilter" aria-controls="storeProductRows" disabled><option value="all">Todos os produtos</option><option value="with_return">Com ocorrência nos pedidos</option><option value="unknown">Com informação pendente</option><option value="without_reported_return">Sem indicação na consulta</option></select></div><div class="field"><label for="storeProductSort">Ordenar por</label><select id="storeProductSort" aria-controls="storeProductRows" disabled><option value="quantity_desc">Mais unidades</option><option value="balance_desc">Maior saldo previsto</option><option value="balance_asc">Menor saldo previsto</option><option value="id_asc">Código do produto</option></select></div><div class="field"><label for="storeProductPageSize">Produtos por página</label><select id="storeProductPageSize" aria-controls="storeProductRows" disabled><option value="20">20 produtos</option><option value="50">50 produtos</option><option value="100">100 produtos</option></select></div></div></details></div><p class="field-help">Busca e filtros consultam todos os produtos. Um produto pode participar de pedidos de vários grupos de devolução. Ordenar pelo saldo previsto ainda não compara lucro líquido.</p><div class="store-product-table-wrap"><table class="store-product-results-table"><thead><tr><th scope="col">Produto e unidades</th><th scope="col">Repasse previsto</th><th scope="col">Custo de produção</th><th scope="col">Imposto previsto · 2%</th><th scope="col">Saldo após produção e imposto</th></tr></thead><tbody id="storeProductRows"></tbody></table></div><div class="product-browser-pagination store-product-pagination" aria-label="Paginação do resultado por produto"><p id="storeProductPageInfo" role="status" aria-live="polite">Preparando a lista…</p><div class="product-page-actions"><button id="storeProductPrevious" type="button" class="button-secondary" aria-controls="storeProductRows" disabled>Anterior</button><button id="storeProductNext" type="button" class="button-secondary" aria-controls="storeProductRows" disabled>Próxima</button></div></div><p class="field-help">Pedidos com vários produtos ficam sem rateio do repasse e do imposto. O repasse parcial de um produto não cobre automaticamente todos os seus custos. O saldo desta lista desconta produção e o imposto associado aos pedidos somente deste produto. Anúncios e outras despesas não foram atribuídos aos produtos; devoluções e recebimentos ainda dependem de conciliação.</p></div></section>
<section id="margins" hidden><div class="card production-costs"><div class="card-head"><div><span class="eyebrow">REFERÊNCIAS CADASTRADAS</span><h2>Custos de produção</h2><p class="muted">Cadastre o custo completo de cada tipo de produto e aplique a vários produtos de uma vez.</p></div><span id="costsVersion" class="badge">Carregando custos…</span></div><form id="productionCostsForm" novalidate><section id="customCostsSection" class="custom-costs-section"><h3>Custos para qualquer produto</h3><p class="muted">Calça, moletom, camiseta ou kit: informe o custo completo de uma unidade vendida. Para um kit, cadastre o custo do kit inteiro; ele não será multiplicado pela quantidade de peças.</p><div id="customCostProfiles"></div><button id="addCustomCostProfile" type="button" class="button-secondary">Adicionar custo personalizado</button><div class="custom-cost-assignment-form"><h3>Aplicar o custo aos produtos</h3><p class="field-help">Uma associação por produto cobre todas as variações atuais e futuras. Use uma variação específica apenas quando seu custo for diferente.</p><div class="field"><label for="customCostItems">Código dos produtos na Shopee</label><textarea id="customCostItems" rows="2" maxlength="21000" placeholder="Ex.: 58269212782, 22199878767" autocomplete="off"></textarea><p class="field-help">Informe um ou vários códigos separados por vírgula ou espaço. Use Configurar custo na lista de Produtos para preencher o código.</p></div><div class="custom-cost-assignment-controls"><div class="field"><label for="customCostProfile">Custo personalizado</label><select id="customCostProfile"><option value="">Cadastre um custo acima</option></select></div><div class="field"><label for="customCostModel">Código da variação · opcional</label><input id="customCostModel" inputmode="numeric" maxlength="20" placeholder="Vazio = todas as variações" autocomplete="off"></div><button id="assignCustomCost" type="button" class="button-secondary">Aplicar custo</button></div><p id="customCostMessage" class="field-help" role="status" aria-live="polite"></p><div id="customCostAssignments" class="custom-cost-assignments"></div></div><p class="field-help">As edições são rascunhos até você usar Salvar custos de produção. Um custo de variação tem prioridade sobre o custo geral do produto.</p></section><div class="standard-shirt-costs"><h3>Padrão de camisetas</h3><p class="field-help">Aplicado aos tamanhos e kits identificados que não tenham um custo personalizado.</p></div><div class="field"><label for="costMode">Como você registra os custos?</label><select id="costMode"><option value="all_inclusive">Custo completo por peça</option><option value="itemized">Custos separados</option></select></div><div id="costInclusive"><div class="cost-pair-grid"><div class="field"><label for="costInclusiveRegular">Camiseta P–GG · custo completo por peça</label><div class="input-unit"><span>R$</span><input id="costInclusiveRegular" inputmode="decimal" autocomplete="off"></div></div><div class="field"><label for="costInclusivePlus">Camiseta G1–G3 · custo completo por peça</label><div class="input-unit"><span>R$</span><input id="costInclusivePlus" inputmode="decimal" autocomplete="off"></div></div></div><p class="field-help">Os valores atuais já incluem camiseta, estampa, etiqueta e embalagem. Componentes separados ficam inativos neste modo.</p></div><div id="costItemized" hidden><div class="cost-pair-grid"><div class="field"><label for="costBaseRegular">Camiseta P–GG · base por peça</label><div class="input-unit"><span>R$</span><input id="costBaseRegular" inputmode="decimal" autocomplete="off" placeholder="Informe a base sem os componentes"></div></div><div class="field"><label for="costBasePlus">Camiseta G1–G3 · base por peça</label><div class="input-unit"><span>R$</span><input id="costBasePlus" inputmode="decimal" autocomplete="off" placeholder="Informe a base sem os componentes"></div></div></div><div class="help-box">Informe a camiseta sem os componentes abaixo. Estampa, etiqueta ou embalagem entram uma única vez: por peça é uma cobrança na camiseta avulsa e duas no kit; por kit é uma cobrança somente no kit. O custo completo anterior fica guardado e não é somado.</div><div id="costComponents"></div><button id="addCostComponent" type="button" class="button-secondary">Adicionar componente</button><p class="field-help">Até 20 componentes. Exemplos: estampa por peça, etiqueta por peça e embalagem por kit.</p></div><div id="costsPreview" class="cost-preview" aria-live="polite"></div><p id="costsDraftNote" class="cost-draft-note"></p><p class="field-help">Custos são referências cadastradas por você, com histórico próprio de versões. A Shopee não informa o custo de produção. Eles ficam separados das margens já cadastradas, que já descontam as peças e taxas.</p><div id="costsNotice" class="alert" hidden role="status" aria-live="polite"></div><div class="form-footer"><div><p id="costsStatus" class="muted" role="status" aria-live="polite">Consultando os custos salvos…</p><div class="actions"><button id="loadProductionCosts" type="button" class="button-link">Carregar custos salvos</button><button id="reviewProductionCosts" type="button" class="button-link" hidden>Revisar custos atuais</button></div></div><button id="saveProductionCosts" disabled>Salvar custos de produção</button></div></form><details class="production-cost-history"><summary>Histórico dos custos de produção</summary><div id="productionCostsAudit" class="cost-audit"><p class="muted">Carregando versões salvas…</p></div></details></div><details class="card advanced-settings"><summary><strong>Referências e simulação de margem</strong><span>Regras cadastradas para kits, antes dos anúncios</span></summary><div class="advanced-content"><div class="card"><div class="card-head"><div><h2>Margem por combinação</h2><p class="muted">Uma camiseta masculina + uma feminina, depois das taxas e dos custos das peças, antes dos anúncios.</p></div><span class="badge">Kit casal</span></div><form id="settings"><div class="grid"><div class="field"><label for="regular">Ambas P–GG</label><div class="input-unit"><span>R$</span><input id="regular" inputmode="decimal" required></div></div><div class="field"><label for="mixed">Uma P–GG + outra G1–G3</label><div class="input-unit"><span>R$</span><input id="mixed" inputmode="decimal" required></div></div><div class="field"><label for="plus">Ambas G1–G3</label><div class="input-unit"><span>R$</span><input id="plus" inputmode="decimal" required></div></div></div><div class="field"><label for="share">Referência de gasto com anúncios · % da margem</label><input id="share" type="number" min="1" max="100" required></div><div class="form-footer"><p class="muted">Novas análises usam a versão salva. O histórico permanece preservado.</p><button>Salvar margens</button></div></form></div><div class="card"><div class="card-head"><div><h2>Simule uma combinação</h2><p class="muted">Veja a margem e a referência antes de analisar o gasto.</p></div></div><div class="grid"><div class="field"><label for="male">Camiseta masculina</label><select id="male">${sizeOptions()}</select></div><div class="field"><label for="female">Camiseta feminina</label><select id="female">${sizeOptions()}</select></div><div class="simulation"><label>Resultado da combinação</label><p id="simulation"></p></div></div><p class="field-help">Campanhas com diferentes tamanhos e quantidades precisam do mix real vendido para confirmar lucro.</p></div></div></details><details class="card advanced-settings"><summary><strong>Conexão e diagnóstico financeiro</strong><span>Conferência de uma amostra e verificações técnicas da integração</span></summary><div class="advanced-content"><div class="card"><div class="card-head"><div><span class="eyebrow">FINANCEIRO · LEITURA</span><h2>Validação financeira</h2><p class="muted">Confira o acesso aos dados financeiros de um pedido concluído criado nos últimos sete dias.</p></div><button id="financeSampleCheck" type="button" class="button-secondary">Validar leitura financeira</button></div><div id="financeSampleStatus" role="status" aria-live="polite"><p class="muted">A consulta será feita quando você clicar em validar.</p></div><details id="financeSampleDetails" hidden><summary>Resultado da validação</summary><pre id="financeSampleResult"></pre><button id="financeSampleCopy" type="button" class="button-secondary">Copiar resultado</button><p id="financeSampleCopyStatus" class="field-help" role="status"></p></details><p class="field-help">Esta etapa confere os campos retornados pela Shopee. Valores recebidos e lucro ainda dependem da conciliação financeira.</p></div><div class="card finance-preview"><div class="card-head"><div><span class="eyebrow">FINANCEIRO · UM PEDIDO</span><h2>Conferência dos valores</h2><p class="muted">Compare os valores de uma amostra com o mesmo pedido na Shopee.</p></div><button id="financePreviewCheck" type="button" class="button-secondary">Conferir valores da amostra</button></div><div id="financePreviewStatus" role="status" aria-live="polite"><p class="muted">A consulta será feita quando você clicar em conferir.</p></div><div id="financePreviewContent" hidden></div><p class="field-help">A prévia aceita pedidos em BRL. Os valores originais em reais foram conferidos com a Shopee; esta prévia os mostra sem conversão. O repasse informado não confirma liquidação ou lucro.</p></div></div></details></section>
<section id="hermes" hidden><div class="section-heading"><span class="eyebrow">INTELIGÊNCIA DA LOJA</span><h2>Hermes</h2><p class="muted">Análises e recomendações para apoiar suas decisões.</p><p id="setup" class="field-help"></p></div><div class="grid stat-grid"><div class="stat-card"><div class="stat-icon">✦</div><small>Análises neste mês</small><div class="stat" id="runsMonth">—</div><p>Execuções solicitadas</p></div><div class="stat-card"><div class="stat-icon">◷</div><small>Modo do Hermes</small><div class="stat" id="mode">—</div><p>Você controla a operação</p></div><div class="stat-card"><div class="stat-icon">◇</div><small>Forma de uso</small><div class="stat" id="billingSummary">—</div><p>Assinatura ou API</p></div></div><div class="source-comparison"><div class="source-card"><span class="eyebrow">LOJA · <span id="storeDay">HOJE</span> · PARCIAL</span><h2>Vendas confirmadas de hoje</h2><strong id="shopOrdersCount">—</strong><div id="shopOrders" role="status" aria-live="polite"><p>Conferindo a situação atual dos pedidos de hoje…</p></div><p id="shopOrdersCutoff" class="field-help"></p><p id="shopOrdersAge" class="field-help"></p><p>Pedidos criados hoje com situação atual de venda confirmada. Cancelados, em cancelamento e não pagos ficam fora deste número. É uma contagem da loja, separada das conversões dos anúncios e dos pedidos concluídos do resumo financeiro.</p></div><div class="source-card ads-source"><span class="eyebrow">SHOPEE ADS · HOJE · PARCIAL</span><h2>Conversões dos anúncios</h2><div id="todayAds">Carregando dados da mesma fonte do dashboard…</div><p id="todayAdsTime" class="field-help"></p><p>A análise do Hermes abaixo usa ontem. Os números de hoje podem mudar durante o dia.</p></div></div><div class="card"><div class="card-head"><div><h2>Seu assistente de decisões</h2><p class="muted">Solicite uma análise e acompanhe o resultado aqui.</p></div><span class="badge">Somente análise</span></div><p id="budgetStatus"></p><div id="runReason" class="alert" hidden></div><div class="actions"><button id="run" class="primary" disabled>Solicitar análise de ontem</button><button id="refresh" class="button-secondary">Atualizar status</button></div><p class="field-help">Na assinatura, o controle usa quantidade de análises. Na API, usa também orçamento e custos reportados. Limites e créditos reais são conferidos no provedor.</p></div><div class="analysis-workspace"><aside class="analysis-history"><div class="card-head"><div><h2>Análises recentes</h2><p class="muted">Selecione um relatório</p></div></div><div id="jobs"></div></aside><div class="analysis-report"><div id="analysisView"><div class="report-empty">Seu próximo relatório aparece aqui. Solicite uma análise para começar.</div></div><p id="timing" class="log-line" hidden></p><p id="autoStatus" class="log-line" role="status">Preparando atualização automática…</p></div></div><details class="card operation-settings"><summary>Configurações do Hermes <span>Modo, horário e limites de uso</span></summary><form id="controls"><div class="grid"><div class="field"><label for="operation">Modo de operação</label><select id="operation"><option value="manual">Manual</option><option value="scheduled">Análise diária agendada</option><option value="paused">Pausado</option></select><p class="field-help">Pausar impede novas análises; uma execução em andamento termina normalmente.</p></div><div class="field"><label for="hour">Hora diária · Brasília</label><input id="hour" type="number" min="0" max="23"></div><div class="field"><label for="billing">Como o Hermes está autenticado?</label><select id="billing"><option value="unverified">Ainda não confirmei</option><option value="subscription">Assinatura ChatGPT/Codex · login</option><option value="api">Chave de API · cobrança por uso</option></select></div></div><div class="help-box" id="billingHelp">A forma de uso deve corresponder à autenticação já configurada no servidor.</div><div class="grid"><div class="field"><label for="runLimit">Limite do painel · análises por mês</label><input id="runLimit" type="number" min="1" max="1000"><p class="field-help">Não representa o limite da sua assinatura no provedor.</p></div><div class="field" id="budgetField"><label for="budget">Orçamento de referência · US$</label><input id="budget" inputmode="decimal"></div><div class="field" id="reserveField"><label for="reserve">Reserva por análise · US$</label><input id="reserve" inputmode="decimal"></div></div><div class="form-footer"><p class="muted">A escolha não muda o provedor nem declara análises gratuitas.</p><button>Salvar operação</button></div></form></details></section>
<section id="products" hidden><form id="bindingsForm"><div class="card product-browser-toolbar"><div class="product-browser-search-row"><div class="field product-browser-search"><label for="productSearch">Buscar produto ou variação</label><input id="productSearch" type="search" autocomplete="off" placeholder="Código, tamanho ou nome do custo" aria-controls="variantCards"></div><button id="itemsRefresh" type="button" class="button-secondary">Atualizar</button></div><div class="product-browser-filter-row"><details id="productFilters" class="product-browser-advanced"><summary>Filtros e ordenação</summary><div class="product-filter-fields"><div class="field"><label for="productStatusFilter">Identificação</label><select id="productStatusFilter" aria-controls="variantCards"><option value="all">Todos os estados</option><option value="ready">Identificados</option><option value="pending">Com pendências</option><option value="draft">Com rascunhos</option></select></div><div class="field"><label for="productTypeFilter">Composição</label><select id="productTypeFilter" aria-controls="variantCards"><option value="all">Todos os tipos</option><option value="kit">Kits</option><option value="single">Camisetas avulsas</option><option value="custom">Custos personalizados</option><option value="unknown">Ainda não definida</option></select></div><div class="field"><label for="productSort">Ordenar por</label><select id="productSort" aria-controls="variantCards"><option value="quantity_desc">Mais unidades no recorte</option><option value="cost_desc">Maior custo unitário</option><option value="cost_asc">Menor custo unitário</option><option value="id_asc">Código do produto</option><option value="pending_first">Pendências primeiro</option></select></div><div class="field"><label for="productPageSize">Produtos por página</label><select id="productPageSize" aria-controls="variantCards"><option value="20">20 produtos</option><option value="50">50 produtos</option><option value="100">100 produtos</option></select></div></div></details><button id="productClearFilters" type="button" class="button-link">Limpar filtros</button></div><p id="productBrowserSummary" class="product-browser-summary" role="status" aria-live="polite"></p><details class="product-browser-scope"><summary>Sobre esta lista</summary><p class="field-help">Produtos dos dados recebidos e dos vínculos salvos. As quantidades incluem os estados retornados pela API; custos usam o perfil cadastrado. A ordenação não representa um ranking de lucro.</p></details></div><div id="variantCards" class="variant-grid"><div class="card"><p class="muted">As variações aparecerão aqui após a consulta.</p></div></div><div class="product-browser-pagination" aria-label="Paginação dos produtos"><p id="productPageInfo" role="status" aria-live="polite">Preparando a lista…</p><div class="product-page-actions"><button id="productPrevious" type="button" class="button-secondary" aria-controls="variantCards" disabled>Anterior</button><button id="productNext" type="button" class="button-secondary" aria-controls="variantCards" disabled>Próxima</button></div></div><div class="card product-automation-bar"><h3>Identificação automática</h3><button id="variantsSync" type="button" class="button-secondary" disabled>Rever identificação</button><p id="variantsSyncStatus" class="field-help" role="status" aria-live="polite"></p><p id="bindingsVersion" class="variant-version"></p><div id="bindingsNotice" class="alert" hidden></div><button id="reviewBindingVersion" type="button" class="button-secondary" hidden>Revisar versão atual</button></div><div class="card form-footer variant-save-footer"><p>Custos personalizados valem por unidade vendida e cobrem o produto ou a variação escolhida. O padrão de camisetas usa uma peça na avulsa e duas no kit casal. As referências de margem desta seção se aplicam somente aos kits de camisetas sem custo personalizado.</p><div class="observation-toolbar"><button id="discardBindingDrafts" type="button" class="button-secondary" disabled>Descartar rascunhos dos vínculos</button><button id="saveBindings" disabled>Salvar vínculos confirmados</button></div></div></form><details class="product-source-review"><summary>Dados da consulta e referências de custo</summary><div class="card"><div class="card-head"><div><span class="eyebrow">ITENS DA LOJA · LEITURA</span><h2>Dados recebidos e referências</h2><p class="muted">Produtos, tamanhos e custos identificados automaticamente a partir do catálogo.</p></div><div class="observation-toolbar"><button id="saveObservation" type="button" disabled>Guardar recorte atual</button></div></div><p id="itemsInfo" class="field-help"></p><div id="itemsStatus" role="status" aria-live="polite">Preparando a consulta dos itens…</div><div id="itemsMetrics" class="report-metrics"></div><div id="itemsReference" class="help-box" hidden></div><div id="itemsProductionCosts" class="help-box production-cost-reference" hidden></div><p id="observationCaptureStatus" class="field-help" role="status" aria-live="polite"></p><p class="field-help">Guardar recorte consulta a fonte novamente e usa os vínculos e as margens <strong>já salvos</strong>. Rascunhos não entram no registro, e o horário do recorte pode avançar.</p><p class="field-help">Quantidades são unidades do catálogo e incluem os status retornados pela API. As linhas por status não são uma contagem de pedidos únicos. Esta leitura não comprova vendas atribuídas aos anúncios nem lucro.</p></div></details></section>
<section id="history" hidden><div class="card"><div class="card-head"><div><h2>Histórico de configurações</h2><p class="muted">Margens e controles versionados para acompanhar suas decisões.</p></div><span class="badge">Auditável</span></div><div id="audit"></div></div><div class="card"><div class="card-head"><div><span class="eyebrow">MEMÓRIA DOS RECORTES</span><h2>Recortes salvos</h2><p class="muted">Consulte o que foi observado e as versões usadas em cada registro.</p></div><button id="observationsRefresh" type="button" class="button-secondary">Atualizar recortes</button></div><p class="field-help">Cada registro é uma leitura parcial do dia até o horário indicado. Não representa o fechamento do dia, vendas pagas ou lucro. Os recortes ainda não são enviados ao Hermes.</p><p id="observationsStatus" class="field-help" role="status" aria-live="polite"></p><div class="observation-workspace"><div><div id="observationsList" class="observation-list"></div><button id="observationsMore" type="button" class="button-secondary observation-more" hidden>Carregar mais recortes</button></div><div id="observationDetail" class="observation-detail"><p class="muted">Selecione um recorte salvo para conferir os detalhes.</p></div></div></div></section>
<section id="roadmap" hidden><div class="card"><div class="card-head"><div><h2>Evolução da operação</h2><p class="muted">O painel e o catálogo já têm automação. A próxima entrega é consolidar os dados necessários para comparar a rentabilidade dos produtos.</p></div><span class="badge">Em evolução</span></div><div class="timeline"><article class="milestone"><h3>1. Consolidar os valores da loja <span class="badge">Em conciliação</span></h3><p>Já disponível: conexão financeira, repasse previsto, custo de produção e resumo por período. Agora o gasto de anúncios é consultado pelas mesmas datas. Já há cobertura de devoluções por pedido. Falta conferir valores reembolsados, itens afetados, recortes das fontes, ajustes e recebimentos para confirmar o resultado líquido.</p></article><article class="milestone"><h3>2. Organizar o catálogo e identificar campeões <span class="badge">Em andamento</span></h3><p>Já disponível: identificação de kits e avulsas, custos por tamanho, consulta compacta, resultado por produto no período financeiro e filtro por ocorrência de devolução nos pedidos. Próximo passo: relacionar contribuição depois dos anúncios, devoluções e estoque a cada produto. Mais unidades vendidas não comprovam maior lucro.</p></article><article class="milestone"><h3>3. Preparar anúncios dos campeões <span class="badge planned">Planejado</span></h3><p>Gerar propostas de campanhas, criativos e orçamento com os dados conciliados. Conferir as permissões oficiais da Shopee e revisar as propostas antes da publicação.</p></article><article class="milestone"><h3>4. Ofertas relâmpago rentáveis <span class="badge planned">Planejado</span></h3><p>Sugerir produtos, preço, desconto, estoque e janela da oferta, preservando uma margem mínima e validando a disponibilidade das APIs de promoção.</p></article><article class="milestone"><h3>5. Automação com metas de lucro <span class="badge planned">Etapa futura</span></h3><p>Ajustar orçamento, pausar ou escalar dentro de limites aprovados e de dados confiáveis. Manter histórico, alertas, controle de perda e botão de pausa.</p></article></div><div class="help-box"><strong>O que libera a próxima etapa</strong><p>Resultado financeiro conferido, gasto de anúncios compatível com o período, devoluções conciliadas e estoque disponível. Com essa base, será possível priorizar os produtos pela contribuição após anúncios e validar as recomendações.</p><p>Criar anúncios e ofertas continua desativado. As consultas de produtos e custos não alteram campanhas.</p></div></div></section>
</main></div></div>`;}

export function adminBody(){
 const original=legacyAdminBody(),opening='<section id="overview">',start=original.indexOf(opening),end=original.indexOf('</section>',start);
 if(start<0||end<start)throw Error('MONTH_VIEW_INSERTION_INVALID');
 const legacy=original.slice(start+opening.length,end);
 return original.slice(0,start)+opening+businessMonthBody()+'<details id="legacyFinanceDetails" class="card monthly-legacy-details" hidden><summary>Referência anterior de pedidos concluídos</summary><p class="field-help">Esta referência preserva a regra antiga por pedido. Para o MEI, use o resumo mensal, que desconta o DAS uma vez no mês.</p>'+legacy+'</details></section>'+original.slice(end+10)+'<div class="workspace-mobile-navigation">'+workspaceNavigation('overview',{role:'owner',mobile:true})+'</div>';
}
